def transform(grid):
    a=[r[:] for r in grid]; H=len(a); W=len(a[0]); bg=max(set(v for r in a for v in r),key=lambda v:sum(r.count(v) for r in a)); seen=set()
    for i in range(H):
        for j in range(W):
            c=a[i][j]
            if c==bg or (i,j) in seen: continue
            stack=[(i,j)]; seen.add((i,j)); ps=[]
            while stack:
                x,y=stack.pop(); ps.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(x+dx,y+dy)
                    if 0<=q[0]<H and 0<=q[1]<W and q not in seen and a[q[0]][q[1]]==c: seen.add(q); stack.append(q)
            r0=min(x for x,y in ps); r1=max(x for x,y in ps); c0=min(y for x,y in ps); c1=max(y for x,y in ps)
            if all(a[r0][y]==c and a[r1][y]==c for y in range(c0,c1+1)) and all(a[x][c0]==c and a[x][c1]==c for x in range(r0,r1+1)):
                fill=2 if (r1-r0)%2==1 and (c1-c0)%2==1 else 7
                for x in range(r0+1,r1):
                    for y in range(c0+1,c1):
                        if a[x][y]==bg: a[x][y]=fill
    return a
